# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BOYLE (P-V) VE CHARLES (V-T) GAZ YASALARI (10.1.9)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">BOYLE YASASI (BASINÇ - HACİM)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Sabit tutulanlar: Madde miktarı (n) ve Sıcaklık (T)</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• İlişki: Basınç (P) ile Hacim (V) TERS orantılıdır</text>\n  <text x="35" y="136" font-size="11.2" fill="#1e3a8a">• Matematiksel Model: P1 · V1 = P2 · V2 = sabit</text>\n  <text x="35" y="160" font-size="11.2" fill="#1e3a8a">• P - V grafiği hiperbol (eğri); P - (1/V) grafiği doğrudur</text>\n  <text x="35" y="184" font-size="11.2" fill="#1e3a8a">• Hacim yarıya inerse birim yüzeye çarpışma 2 katına çıkar</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">CHARLES YASASI (HACİM - SICAKLIK)</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Sabit tutulanlar: Madde miktarı (n) ve Basınç (P)</text>\n  <text x="370" y="112" font-size="11.2" fill="#14532d">• İlişki: Hacim (V) ile Mutlak Sıcaklık (T) DOĞRU orantılıdır</text>\n  <text x="370" y="136" font-size="11.2" fill="#14532d">• Matematiksel Model: V1 / T1 = V2 / T2 = sabit</text>\n  <text x="370" y="160" font-size="11.2" fill="#14532d">• Mutlak Sıcaklık: T(K) = t(°C) + 273  (Mutlak sıfır: 0 K)</text>\n  <text x="370" y="184" font-size="11.2" fill="#14532d">• Elastik balon veya sürtünmesiz pistonlu kapta gözlenir</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Tüm gaz yasalarında sıcaklık hesaplamaları daima Kelvin (T = °C + 273) cinsinden yapılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">GAY-LUSSAC (P-T) VE AVOGADRO (V-n) GAZ YASALARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">GAY-LUSSAC YASASI (BASINÇ - SICAKLIK)</text>\n  <text x="35" y="88" font-size="11.2" fill="#7f1d1d">• Sabit tutulanlar: Madde miktarı (n) ve Hacim (V)</text>\n  <text x="35" y="112" font-size="11.2" fill="#7f1d1d">• İlişki: Basınç (P) ile Mutlak Sıcaklık (T) DOĞRU orantılıdır</text>\n  <text x="35" y="136" font-size="11.2" fill="#7f1d1d">• Matematiksel Model: P1 / T1 = P2 / T2 = sabit</text>\n  <text x="35" y="160" font-size="11.2" fill="#7f1d1d">• Sabit hacimli çelik kapta T artarsa tanecik hızı artar</text>\n  <text x="35" y="184" font-size="11.2" fill="#7f1d1d">• Çarpışma şiddeti ve sıklığı arttığı için basınç yükselir</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">AVOGADRO YASASI (HACİM - MOL SAYISI)</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• Sabit tutulanlar: Basınç (P) ve Sıcaklık (T)</text>\n  <text x="370" y="112" font-size="11.2" fill="#581c87">• İlişki: Hacim (V) ile Mol Sayısı (n) DOĞRU orantılıdır</text>\n  <text x="370" y="136" font-size="11.2" fill="#581c87">• Matematiksel Model: V1 / n1 = V2 / n2 = sabit</text>\n  <text x="370" y="160" font-size="11.2" fill="#581c87">• Normal Koşullar (NK: 0 °C, 1 atm) → 1 mol gaz = 22,4 L</text>\n  <text x="370" y="184" font-size="11.2" fill="#581c87">• Standart Koşullar (OK: 25 °C, 1 atm) → 1 mol gaz = 24,5 L</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Aynı basınç ve sıcaklıkta eşit hacimli ideal gazlarda eşit sayıda tanecik (mol) bulunur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BİRLEŞTİRİLMİŞ GAZ DENKLEMİ VE KİNETİK TEORİ YORUMU</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">GENEL VE İDEAL GAZ DENKLEMLERİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#7c2d12">• Birleştirilmiş Gaz Denklemi:</text>\n  <text x="35" y="108" font-size="11.5" font-weight="bold" fill="#7c2d12">  (P1 · V1) / (n1 · T1) = (P2 · V2) / (n2 · T2)</text>\n  <text x="35" y="132" font-size="11.2" fill="#7c2d12">• İdeal Gaz Denklemi: P · V = n · R · T</text>\n  <text x="35" y="156" font-size="11.2" fill="#7c2d12">• R = 0,082 L·atm/(mol·K) veya 22,4 / 273 L·atm/(mol·K)</text>\n  <text x="35" y="180" font-size="11.2" fill="#7c2d12">• Sabit olan değişkenler denklemden sadeleştirilir</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">KİNETİK MOLEKÜLER TEORİ İLE DEĞERLENDİRME</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• Gaz basıncının kaynağı: Taneciklerin çepere esnek çarpması</text>\n  <text x="370" y="112" font-size="11.2" fill="#064e3b">• Ortalama kinetik enerji (Ek) mutlak sıcaklığa (T) bağlıdır</text>\n  <text x="370" y="136" font-size="11.2" fill="#064e3b">• T sabitken V azalırsa: Tanecik hızı değişmez, sıklık artar</text>\n  <text x="370" y="160" font-size="11.2" fill="#064e3b">• V sabitken T artarsa: Hem hız hem çarpışma sıklığı artar</text>\n  <text x="370" y="184" font-size="11.2" fill="#064e3b">• Yüksek sıcaklık ve düşük basınçta gazlar ideale yaklaşır</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Farklı gazların aynı Kelvin sıcaklığında (T) ortalama kinetik enerjileri birbirine eşittir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
